import json
from playwright.sync_api import sync_playwright
URL='http://127.0.0.1:28494'
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True);ctx=browser.new_context();page=ctx.new_page();page.goto(URL);page.locator('#newDialog[open]').wait_for();page.locator('#newName').fill('大纲重试');page.get_by_role('button',name='创建',exact=True).click();page.wait_for_function('paperpilot.current?.project?.id');pid=page.evaluate('paperpilot.current.project.id');page.locator('[data-tab="outline"]').click();page.locator('#outlineNodeCreate').wait_for();page.wait_for_function("document.querySelector('#outlineTree').textContent.includes('暂无结构化节点')");events=[];lost={'next':True}
 def intercept(route):
  body=json.loads(route.request.post_data);events.append(body)
  if lost['next']:
   lost['next']=False;response=route.fetch();assert response.ok,response.text();route.fulfill(status=503,content_type='application/json',body='{"detail":{"message":"模拟响应丢失"}}')
  else:route.continue_()
 page.route('**/outline/nodes',intercept);page.locator('#outlineNodeTitle').fill('只创建一次');page.locator('#outlineNodeCreate').click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('结果未确认')");graph=ctx.request.get(f'{URL}/api/projects/{pid}/outline/structured').json();assert graph['version']==1 and len(graph['nodes'])==1
