 lost['next']=True;delete=page.get_by_role('button',name='删除节点 只创建一次');delete.wait_for();page.once('dialog',lambda d:d.accept());delete.click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('结果未确认')");assert ctx.request.get(f'{URL}/api/projects/{pid}/outline/structured').json()['version']==2;page.once('dialog',lambda d:d.accept());delete.click();page.wait_for_function("document.querySelector('#outlineTree').textContent.includes('暂无结构化节点')");assert events[2]==events[3];graph=ctx.request.get(f'{URL}/api/projects/{pid}/outline/structured').json();assert graph['version']==2 and not graph['nodes']
 lost['next']=True;page.locator('#outlineNodeTitle').fill('待核对节点');page.locator('#outlineNodeCreate').click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('结果未确认')");page.locator('#outlineNodeTitle').fill('新输入');page.locator('#outlineNodeCreate').click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('请先刷新树')");page.locator('#outlineNodeRefresh').click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('已刷新大纲')");assert '待核对节点' in page.locator('#outlineTree').inner_text();assert page.locator('#outlineNodeTitle').input_value()=='新输入';page.locator('#outlineNodeCreate').click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('节点已保存')");graph=ctx.request.get(f'{URL}/api/projects/{pid}/outline/structured').json();assert graph['version']==4 and {n['title'] for n in graph['nodes']}=={'待核对节点','新输入'}
 page.locator('#outlineTree .outline-node-select').filter(has_text='新输入').click();page.locator('#outlineDetailTitle').fill('修改后标题');lost['next']=True;before=len(events);page.locator('#outlineNodeSave').click();page.wait_for_function("document.querySelector('#outlineNodeDraftStatus').textContent.includes('结果未确认')");page.locator('#outlineNodeSave').click();page.wait_for_function("document.querySelector('#outlineOperationStatus').textContent.includes('节点已保存为新版本')");assert events[before]==events[before+1];graph=ctx.request.get(f'{URL}/api/projects/{pid}/outline/structured').json();assert graph['version']==5 and any(n['title']=='修改后标题' for n in graph['nodes']);browser.close();print('lost responses replay and refresh reconciles unknown outcomes')
